class Solution {
  public int totalFruit(int[] fruits) {
    Map<Integer, Integer> count = new HashMap<>();
    int left = 0;
    int best = 0;

    for (int right = 0; right < fruits.length; right++) {
      count.put(fruits[right], count.getOrDefault(fruits[right], 0) + 1);

      while (count.size() > 2) {
        int fruit = fruits[left++];
        count.put(fruit, count.get(fruit) - 1);
        if (count.get(fruit) == 0) {
          count.remove(fruit);
        }
      }

      best = Math.max(best, right - left + 1);
    }

    return best;
  }
}

class Solution {
  public int longestOnes(int[] nums, int k) {
    int left = 0;
    int zeroes = 0;
    int best = 0;

    for (int right = 0; right < nums.length; right++) {
      if (nums[right] == 0) {
        zeroes++;
      }
      while (zeroes > k) {
        if (nums[left++] == 0) {
          zeroes--;
        }
      }
      best = Math.max(best, right - left + 1);
    }

    return best;
  }
}

class Solution {
  public int characterReplacement(String s, int k) {
    int[] count = new int[26];
    int left = 0;
    int maxFrequency = 0;
    int best = 0;

    for (int right = 0; right < s.length(); right++) {
      int index = s.charAt(right) - 'A';
      count[index]++;
      maxFrequency = Math.max(maxFrequency, count[index]);

      while (right - left + 1 - maxFrequency > k) {
        count[s.charAt(left) - 'A']--;
        left++;
      }

      best = Math.max(best, right - left + 1);
    }

    return best;
  }
}

class Solution {
  public int maxSatisfied(int[] customers, int[] grumpy, int minutes) {
    int baseSatisfied = 0;
    int windowGain = 0;

    for (int i = 0; i < customers.length; i++) {
      if (grumpy[i] == 0) {
        baseSatisfied += customers[i];
      } else if (i < minutes) {
        windowGain += customers[i];
      }
    }

    int bestGain = windowGain;
    for (int right = minutes; right < customers.length; right++) {
      if (grumpy[right] == 1) {
        windowGain += customers[right];
      }
      if (grumpy[right - minutes] == 1) {
        windowGain -= customers[right - minutes];
      }
      bestGain = Math.max(bestGain, windowGain);
    }

    return baseSatisfied + bestGain;
  }
}

