class Solution {
  public int[] maxSlidingWindow(int[] nums, int k) {
    Deque<Integer> deque = new ArrayDeque<>();
    int[] answer = new int[nums.length - k + 1];

    for (int right = 0; right < nums.length; right++) {
      while (!deque.isEmpty() && deque.peekFirst() <= right - k) {
        deque.pollFirst();
      }
      while (!deque.isEmpty() && nums[deque.peekLast()] <= nums[right]) {
        deque.pollLast();
      }
      deque.offerLast(right);

      if (right >= k - 1) {
        answer[right - k + 1] = nums[deque.peekFirst()];
      }
    }

    return answer;
  }
}

class Solution {
  public String minWindow(String s, String t) {
    int[] need = new int[128];
    for (char c : t.toCharArray()) {
      need[c]++;
    }

    int missing = t.length();
    int left = 0;
    int start = 0;
    int best = Integer.MAX_VALUE;

    for (int right = 0; right < s.length(); right++) {
      if (need[s.charAt(right)]-- > 0) {
        missing--;
      }

      while (missing == 0) {
        if (right - left + 1 < best) {
          best = right - left + 1;
          start = left;
        }
        if (++need[s.charAt(left++)] > 0) {
          missing++;
        }
      }
    }

    return best == Integer.MAX_VALUE ? "" : s.substring(start, start + best);
  }
}

class Solution {
  public int numSubarrayProductLessThanK(int[] nums, int k) {
    if (k <= 1) return 0;
    int left = 0;
    int count = 0;
    long product = 1;
    for (int right = 0; right < nums.length; right++) {
      product *= nums[right];
      while (product >= k) {
        product /= nums[left++];
      }
      count += right - left + 1;
    }
    return count;
  }
}

class Solution {
  public int longestSubarray(int[] nums) {
    int left = 0;
    int zeros = 0;
    int best = 0;
    for (int right = 0; right < nums.length; right++) {
      if (nums[right] == 0) zeros++;
      while (zeros > 1) {
        if (nums[left++] == 0) zeros--;
      }
      best = Math.max(best, right - left);
    }
    return best;
  }
}

class Solution {
  public int numberOfSubstrings(String s) {
    int[] count = new int[3];
    int left = 0;
    int answer = 0;
    for (int right = 0; right < s.length(); right++) {
      count[s.charAt(right) - 'a']++;
      while (count[0] > 0 && count[1] > 0 && count[2] > 0) {
        answer += s.length() - right;
        count[s.charAt(left++) - 'a']--;
      }
    }
    return answer;
  }
}

class Solution {
  public int numberOfSubarrays(int[] nums, int k) {
    return atMost(nums, k) - atMost(nums, k - 1);
  }

  private int atMost(int[] nums, int k) {
    int left = 0;
    int answer = 0;
    for (int right = 0; right < nums.length; right++) {
      if (nums[right] % 2 == 1) k--;
      while (k < 0) {
        if (nums[left++] % 2 == 1) k++;
      }
      answer += right - left + 1;
    }
    return answer;
  }
}

class Solution {
  public int findMaxConsecutiveOnes(int[] nums) {
    int current = 0;
    int best = 0;
    for (int num : nums) {
      current = num == 1 ? current + 1 : 0;
      best = Math.max(best, current);
    }
    return best;
  }
}

class Solution {
  public int maxScore(int[] cardPoints, int k) {
    int total = 0;
    for (int point : cardPoints) total += point;

    int keep = cardPoints.length - k;
    if (keep == 0) return total;

    int window = 0;
    for (int i = 0; i < keep; i++) window += cardPoints[i];
    int minWindow = window;
    for (int right = keep; right < cardPoints.length; right++) {
      window += cardPoints[right] - cardPoints[right - keep];
      minWindow = Math.min(minWindow, window);
    }
    return total - minWindow;
  }
}

